module fsm #(
    parameter s0 = 3'b000,
    parameter s1 = 3'b001,
    parameter s2 = 3'b010,
    parameter s3 = 3'b011,
    parameter s4 = 3'b100,
    parameter s5 = 3'b101
) (
    input IN,
    output reg MATCH,
    input CLK,
    input RST
);


reg [2:0] state, next_state;

always @(posedge CLK or posedge RST) begin
    if (RST) state <= s0; else state <= next_state;
end

always @(*) begin
    case (state)
        s0: if (IN == 1'b1) next_state = s1; else next_state = s0;
        s1: if (IN == 1'b0) next_state = s2; else next_state = s1;
        s2: if (IN == 1'b0) next_state = s3; else next_state = s2;
        s3: if (IN == 1'b1) next_state = s4; else next_state = s3;
        s4: if (IN == 1'b1) next_state = s5; else next_state = s4;
        s5: if (IN == 1'b0) next_state = s0; else next_state = s5;
        default: next_state = s0;
    endcase
end

assign MATCH = (state == s5) && (IN == 1'b0);

endmodule

